[
  {
    "statement": "The most effective interventions for creating and managing aquatic habitats for amphibians in agricultural landscapes include pond creation, wetland creation, pond restoration, fish removal, and ditch management.",
    "citations": []
  },
  {
    "statement": "Pond creation for amphibians demonstrates high effectiveness.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Studies have shown that amphibians used 64-100% of created ponds and reproduced in 64-68% of those ponds.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Depending on the species, amphibians used 8-100% of created ponds and reproduced in 2-62% of them.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "All 28 studies investigating colonization found that amphibians used some or all created ponds.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Created ponds supported up to 15 naturally colonizing amphibian species and up to 10 species that reproduced.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Five studies found that the numbers of amphibian species or breeding species were similar or higher in created ponds compared to natural ponds.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Wetland creation is an effective intervention for amphibians.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "Five site comparison studies showed that created wetlands had similar numbers of amphibian species, amphibian abundance, or amphibian communities to natural wetlands.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "Studies found that four to 15 amphibian species used or colonized created wetlands.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "A global review found that numbers of amphibian species and their abundance in created wetlands were higher or similar to natural wetlands in 54% of studies reviewed.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "A global review found that numbers of amphibian species and their abundance in created wetlands were similar to natural wetlands in 35% of studies reviewed.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "Pond restoration demonstrates mixed but generally positive results for amphibians.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Six replicated studies showed that pond restoration and creation increased numbers of amphibian species, maintained or increased amphibian populations, or increased pond occupancy and breeding success.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Restored and created ponds were colonized by one to seven amphibian species.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Between 6% and 65% of restored and created ponds were colonized by amphibians, and 35% were used for breeding.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Fish removal through pond drying significantly enhances amphibian habitat quality.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "One study showed that draining ponds to eliminate fish increased the numbers of amphibian species.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "Studies found that pond drying to eliminate fish increased the breeding success of frog or newt species.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "Ditch management in agricultural landscapes provides benefits for amphibians.",
    "citations": [
      "749"
    ]
  },
  {
    "statement": "One study found that the numbers of amphibian species and their abundance was significantly higher in ditches managed under agri-environment schemes compared to those managed conventionally.",
    "citations": [
      "749"
    ]
  },
  {
    "statement": "Another study found that managing ditches increased common toad numbers.",
    "citations": [
      "749"
    ]
  },
  {
    "statement": "Water level regulation can support amphibian populations.",
    "citations": [
      "833",
      "853"
    ]
  },
  {
    "statement": "Studies show that maintaining pond water levels increased natterjack toad populations, maintained newt populations, and enabled successful breeding by dusky gopher frogs.",
    "citations": [
      "833"
    ]
  },
  {
    "statement": "Retaining connectivity between habitat patches maintained populations of eight of 13 frog species over 20 years.",
    "citations": [
      "853"
    ]
  }
]

[
  {
    "statement": "Several interventions are available for creating or providing shelter habitats for amphibians.",
    "citations": []
  },
  {
    "statement": "Creating artificial hibernacula or aestivation sites for amphibians has been studied.",
    "citations": []
  },
  {
    "statement": "One replicated before-and-after study in the UK found that providing artificial hibernacula, along with other terrestrial habitat management, maintained populations of great crested newts.",
    "citations": [
      "759"
    ]
  },
  {
    "statement": "A replicated study in the UK found that created hibernacula were used by common frog and smooth newts, but not great crested newts.",
    "citations": [
      "759"
    ]
  },
  {
    "statement": "A study in the UK found four amphibian species close to created hibernacula at two of three sites.",
    "citations": [
      "759"
    ]
  },
  {
    "statement": "Creating refuges for amphibians involves adding coarse woody debris to forest floors.",
    "citations": []
  },
  {
    "statement": "Two replicated controlled studies in the USA and Indonesia found mixed effects on the abundance of individual amphibian species after adding coarse woody debris to forest floors.",
    "citations": [
      "772"
    ]
  },
  {
    "statement": "A before-and-after study in Australia found that restoration which included reintroducing coarse woody debris to the forest floor increased frog species.",
    "citations": [
      "772"
    ]
  },
  {
    "statement": "A replicated before-and-after study in the UK found that creating refugia for great crested newts, along with other interventions, maintained four populations.",
    "citations": [
      "772"
    ]
  },
  {
    "statement": "Two studies in New Zealand and the USA found that artificial refugia were used by translocated Hamilton's frogs and hellbenders.",
    "citations": [
      "772"
    ]
  },
  {
    "statement": "Leaving coarse woody debris in forests shows varied results for amphibians.",
    "citations": []
  },
  {
    "statement": "A replicated controlled study in the USA found that migrating amphibians used clearcuts where woody debris was retained more than where woody debris was removed.",
    "citations": [
      "843"
    ]
  },
  {
    "statement": "A study found that the survival of juvenile amphibians was significantly higher in piles of woody debris than in open areas.",
    "citations": [
      "843"
    ]
  },
  {
    "statement": "No evidence was found for the effects on amphibian populations of creating refuge areas specifically in aquatic habitats.",
    "citations": [
      "813"
    ]
  }
]

[
  {
    "statement": "Several key factors and interventions have influenced the success of natterjack toad conservation projects in the UK.",
    "citations": []
  },
  {
    "statement": "Translocation efforts have shown that re-establishing natterjack toads on dune or saltmarsh habitat was more successful than on heathland.",
    "citations": [
      "859"
    ]
  },
  {
    "statement": "Translocations of natterjack toads resulted in breeding populations being established at 30-70% of sites.",
    "citations": [
      "859"
    ]
  },
  {
    "statement": "Replicated translocations of wild natterjack toads have shown more success than translocations of captive-bred toads.",
    "citations": [
      "859"
    ]
  },
  {
    "statement": "Pond creation has been a crucial intervention for natterjack toad conservation.",
    "citations": [
      "866"
    ]
  },
  {
    "statement": "Studies show that created ponds, along with other interventions, significantly increased natterjack toad populations.",
    "citations": [
      "866"
    ]
  },
  {
    "statement": "Created ponds, along with other interventions, maintained or increased natterjack toad populations at 75% of sites.",
    "citations": [
      "866"
    ]
  },
  {
    "statement": "Created ponds had lower tadpole mortality from desiccation compared to natural ponds.",
    "citations": [
      "866"
    ]
  },
  {
    "statement": "Created ponds had higher tadpole mortality from predation by invertebrates compared to natural ponds.",
    "citations": [
      "866"
    ]
  },
  {
    "statement": "Habitat management through vegetation clearance has been an effective conservation method.",
    "citations": [
      "761"
    ]
  },
  {
    "statement": "Vegetation clearance along with other habitat management increased, stabilized or maintained natterjack toad populations.",
    "citations": [
      "761"
    ]
  },
  {
    "statement": "Vegetation clearance resulted in increased occupancy by natterjack toads.",
    "citations": [
      "761"
    ]
  },
  {
    "statement": "Water chemistry management through adding limestone to ponds has shown mixed results.",
    "citations": [
      "748"
    ]
  },
  {
    "statement": "Adding limestone to ponds resulted in the establishment of one of three translocated natterjack toad populations.",
    "citations": [
      "748"
    ]
  },
  {
    "statement": "Adding limestone to ponds increased natterjack toad populations when combined with species-specific habitat management.",
    "citations": [
      "748"
    ]
  },
  {
    "statement": "Adding limestone to ponds temporarily increased breeding.",
    "citations": [
      "748"
    ]
  },
  {
    "statement": "In some cases, adding limestone to ponds resulted in high tadpole mortality and pond abandonment.",
    "citations": [
      "748"
    ]
  },
  {
    "statement": "Grazing management has been incorporated into successful natterjack toad conservation strategies.",
    "citations": [
      "780"
    ]
  },
  {
    "statement": "Habitat management that included the reintroduction of grazing helped to maintain or increase natterjack toad populations.",
    "citations": [
      "780"
    ]
  },
  {
    "statement": "The combination of multiple interventions appears important for natterjack toad conservation.",
    "citations": []
  },
  {
    "statement": "Studies consistently show success when translocation, habitat management, and pond creation are implemented together.",
    "citations": []
  }
]

[
  {
    "statement": "Captive breeding programs for amphibians show mixed results across different amphibian groups with varying levels of success and challenges.",
    "citations": []
  },
  {
    "statement": "In 23 of 33 studies on frogs, the amphibians produced eggs in captivity.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Some cases of captive egg production for frogs involved captive-bred females.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Seven studies found mixed results, with some frog species or 17-50% of captive populations reproducing successfully.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "In some studies, other frog species were difficult to maintain or raise to adults.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Seventeen studies found that captive-bred frogs were raised successfully to hatching, tadpoles, froglets, or adults.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "One study on captive frog breeding found low froglet survival.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Another study found three frog species could not be successfully raised to adulthood.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Specific success rates for captive frog breeding included 30-88% of eggs hatching or 75% survival to metamorphosis.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Specific survival rates for captive-bred frogs included 17-51% for froglets and 50-90% for adults.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "For salamanders and newts, four of six studies found that eggs were produced successfully in captivity.",
    "citations": [
      "838"
    ]
  },
  {
    "statement": "One case of successful egg production for salamanders and newts involved captive-bred females.",
    "citations": [
      "838"
    ]
  },
  {
    "statement": "Two studies on salamanders and newts found that egg production depended on tank habitat.",
    "citations": [
      "838"
    ]
  },
  {
    "statement": "Two studies found that egg production for salamanders and newts was more successful in semi-natural conditions compared to laboratory conditions.",
    "citations": [
      "838"
    ]
  },
  {
    "statement": "One study found 60% of Japanese giant salamander eggs survived to hatching in captivity.",
    "citations": [
      "838"
    ]
  },
  {
    "statement": "One review noted that slimy salamanders produced eggs in captivity that did not hatch.",
    "citations": [
      "838"
    ]
  },
  {
    "statement": "Head-starting programs involve captive rearing of amphibians from eggs for later release.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Six of 10 studies on head-starting programs found that released tadpoles, metamorphs, or juveniles established breeding populations or increased frog and toad populations.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Nine of 10 studies found that head-started amphibians released at various life stages metamorphosed successfully.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Nine of 10 studies found that head-started amphibians tended to survive the first season, winter, or year after release.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Nine of 10 studies found that head-started amphibians bred successfully after release.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "A key challenge for captive amphibian breeding is the need for specific environmental conditions.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "The reproductive success of captive amphibians depended on temperature or simulated wet and dry seasons.",
    "citations": [
      "835"
    ]
  },
  {
    "statement": "Hormone treatment to induce breeding in amphibians showed mixed results.",
    "citations": [
      "883"
    ]
  },
  {
    "statement": "Between 30-71% of female amphibians produced viable eggs following hormone treatment, depending on hormone combinations and dosages.",
    "citations": [
      "883"
    ]
  },
  {
    "statement": "Some captive breeding programs required working with surrogate species first to establish husbandry techniques before working with target species.",
    "citations": [
      "1862"
    ]
  },
  {
    "statement": "For conservation purposes, 41% of release programs of captive-bred or head-started amphibians showed evidence of breeding in the wild for multiple generations.",
    "citations": [
      "871"
    ]
  },
  {
    "statement": "29% of release programs of captive-bred or head-started amphibians showed some evidence of breeding in the wild.",
    "citations": [
      "871"
    ]
  },
  {
    "statement": "12% of release programs of captive-bred or head-started amphibians showed evidence of survival following release.",
    "citations": [
      "871"
    ]
  }
]

[
  {
    "statement": "Several actions can be taken to restore or enhance existing water bodies for amphibians as alternatives to creating new ponds.",
    "citations": []
  },
  {
    "statement": "Pond restoration has been shown to have varying effectiveness, with mixed effects depending on the site and species.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Pond restoration has been shown to increase the numbers of amphibian species.",
