  {
    "statement": "Fish control in ponds can be achieved by drying the ponds out.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "Drying out ponds for fish control has been found to increase the numbers of amphibian species.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "Drying out ponds for fish control has increased the breeding success of frog and newt species.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "Disease management is possible through pond treatments to remove chytrid fungus.",
    "citations": [
      "766"
    ]
  },
  {
    "statement": "Studies found that treating ponds for chytrid fungus reduced infection levels but did not eradicate the disease.",
    "citations": [
      "766"
    ]
  }
