[
  {
    "statement": "Evidence shows several direct treatment methods for amphibians infected with chytridiomycosis have varying degrees of effectiveness.",
    "citations": []
  },
  {
    "statement": "Antifungal treatments show the strongest evidence for treating amphibians with chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
